using ValveResourceFormat;using ValveResourceFormat.ResourceTypes;using ValveResourceFormat.Serialization.KeyValues;using System.Text.Json;
var sets=new List<object>();foreach(var dir in args.Skip(1)){var rows=new List<object>();int wordsErrors=0,bytesErrors=0,total=0;foreach(var f in Directory.GetFiles(dir,"*.vnmclip_c",SearchOption.AllDirectories)){using var r=new Resource();r.Read(f);var kv=((BinaryKV3)r.DataBlock!).Data.Root;int offset=0,we=0,be=0;foreach(var s in kv.GetArray("m_trackCompressionSettings")){int actual=s.GetInt32Property("m_nTrackReadOffset");if(actual!=offset)we++;if(actual!=offset*2)be++;offset+=(s.GetBooleanProperty("m_bIsRotationStatic")?0:3)+(s.GetBooleanProperty("m_bIsTranslationStatic")?0:3)+(s.GetBooleanProperty("m_bIsScaleStatic")?0:1);total++;}wordsErrors+=we;bytesErrors+=be;rows.Add(new{clip=Path.GetFileName(f),we,be,frameWords=offset,samplingChain=kv.GetIntegerArray("m_modelSpaceSamplingChain"),samplingIndices=kv.GetIntegerArray("m_modelSpaceBoneSamplingIndices")});}sets.Add(new{dir,total,wordsErrors,bytesErrors,rows});}File.WriteAllText(args[0],JsonSerializer.Serialize(sets,new JsonSerializerOptions{WriteIndented=true}));
